-- Rollback of migration 007 (publication), generated by focus.migrations.rollback_script from the forward
-- script's declared objects. Recovery is forward by default; this exists for an install that has just failed review.
-- The runner executes it in one transaction under sp_getapplock('FOCUS_FN_MIGRATIONS'); any guard stops it whole.
-- Nothing here deletes a row.
SET XACT_ABORT ON;
DROP VIEW IF EXISTS WEB_APP.FOCUS_FN_CurrentPlan;
DROP PROCEDURE IF EXISTS WEB_APP.FOCUS_FN_AcceptPlan;
DROP PROCEDURE IF EXISTS WEB_APP.FOCUS_FN_RecordValidation;
DROP PROCEDURE IF EXISTS WEB_APP.FOCUS_FN_ReadPlanStage;
DROP PROCEDURE IF EXISTS WEB_APP.FOCUS_FN_StagePlan;
DROP TRIGGER IF EXISTS WEB_APP.TR_FN_FrozenGoal_Immutable;
DROP TRIGGER IF EXISTS WEB_APP.TR_FN_PublishedPlan_Immutable;
DROP TRIGGER IF EXISTS WEB_APP.TR_FN_Validation_Immutable;
DROP TRIGGER IF EXISTS WEB_APP.TR_FN_PlanStage_Immutable;
ALTER TABLE WEB_APP.FOCUS_FN_PlanHead DROP CONSTRAINT IF EXISTS CK_FN_PlanHead_Version;
ALTER TABLE WEB_APP.FOCUS_FN_PublishedPlan DROP CONSTRAINT IF EXISTS CK_FN_PublishedPlan_Purpose;
ALTER TABLE WEB_APP.FOCUS_FN_Validation DROP CONSTRAINT IF EXISTS CK_FN_Validation_Counts;
ALTER TABLE WEB_APP.FOCUS_FN_Validation DROP CONSTRAINT IF EXISTS CK_FN_Validation_Kind;
ALTER TABLE WEB_APP.FOCUS_FN_PlanStage DROP CONSTRAINT IF EXISTS CK_FN_PlanStage_Sha;
ALTER TABLE WEB_APP.FOCUS_FN_PlanStage DROP CONSTRAINT IF EXISTS CK_FN_PlanStage_Purpose;
